// Cherche d'abord un numéro de commande dans le message client
// Format Alltricks : 260507T074339522 ou 260507T074339522A
const msg = $json.dernier_message || '';
const sfRef = $json.name || '';
const match = msg.match(/\b(\d{6}[A-Z]\d{12}[A-Z]?)\b/);
const order_ref = match ? match[1] : sfRef;

return {
  json: {
    order_ref,
    contact_email: $json.contact_email || '',
    case_id: $json.case_id || '',
    contact_firstname: $json.contact_firstname || '',
    langue: $json.langue || 'fr',
    dernier_message: $json.dernier_message || '',
    site: $json.site_de_la_commande || 'Alltricks',
    motif_contact: $json.motif_contact || '',
    montant_ttc: $json.montant_ttc || 0,
  }
};

const ctx = $('Extraire référence commande').item.json;
const wtOrder = $('WT — Order Details').item.json;
const wtTracking = $('WT — Tracking').item.json;

return {
  json: {
    ...ctx,
    wt_order: wtOrder,
    wt_tracking: wtTracking,
  }
};

