const raw = ($json.output || '').trim();
let result = {
  out_of_scope: false,
  needs_human: true,
  order_reference: null,
  tracking_number: null,
  situation_category: 'PAS_DE_TRACKING',
  situation_detail: 'Erreur de parsing de la réponse IA',
  email_subject: '',
  email_body: '',
  language: 'fr'
};

try {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    const parsed = JSON.parse(match[0]);
    result = {
      out_of_scope: parsed.out_of_scope || false,
      needs_human: parsed.needs_human || false,
      order_reference: parsed.order_reference || null,
      tracking_number: parsed.tracking_number || null,
      situation_category: parsed.situation_category || 'PAS_DE_TRACKING',
      situation_detail: parsed.situation_detail || '',
      email_subject: parsed.email_subject || '',
      email_body: parsed.email_body || '',
      language: parsed.language || 'fr',
    };
  }
} catch(e) {
  console.error('Parsing JSON échoué:', e.message);
}

return {
  json: {
    ...result,
    contact_email: $('Extraire référence commande').item.json.contact_email,
    case_id: $('Extraire référence commande').item.json.case_id,
  }
};
